import{_ as p,H as e,f as _,i as t}from"./chunks/framework.BH2BK_3i.js";const f=JSON.parse('{"title":"旅程再启 | 不断向前演进的消息队列","description":"","frontmatter":{},"headers":[],"relativePath":"深入拆解消息队列47讲/旅程再启｜不断向前演进的消息队列.md","filePath":"深入拆解消息队列47讲/旅程再启｜不断向前演进的消息队列.md","lastUpdated":1795450178000}'),r={name:"深入拆解消息队列47讲/旅程再启｜不断向前演进的消息队列.md"};function l(i,a,o,s,n,d){return e(),_("div",null,[...a[0]||(a[0]=[t('<h1 id="旅程再启-不断向前演进的消息队列" tabindex="-1">旅程再启 | 不断向前演进的消息队列 <a class="header-anchor" href="#旅程再启-不断向前演进的消息队列" aria-label="Permalink to &quot;旅程再启 | 不断向前演进的消息队列&quot;">​</a></h1><p>你好，我是文强，好久不见！</p><p>在专栏结束了一年以后，我决定对课程进行一次迭代，分享一些新的认知。</p><p>消息队列作为系统架构中必不可少的基础软件，其重要性不言而喻。基于性能、稳定性、成本等等方面的考虑，MQ 也是不断向前演进的，不会一直停留在前十年的产品。比如，你会看到：用 C++ 重写的 Kafka——Redpanda，用 Go 重写的 Kafka——WrapStream，用 Java 实现消息引擎 Ursa 的 Pulsar Ursa……它们在商业上都取得了不同程度的成功。</p><p>我们需要向外看，跟随消息队列技术领域的发展趋势，从使用者视角，去做与业务更加匹配的技术选型。同时，也可以从技术视角，去拆解业界的代表产品，多多积累，这是一种很好的学习方式。</p><p>因此，这次加餐我主要会集中在两个方向：消息队列技术演进与业界优秀产品拆解。</p><p>目前拟定增加的话题如下：</p><ol><li><p>2024：关于消息队列未来技术演进的思考</p></li><li><p>再聊存储：存算分离、分层存储、对象存储</p></li><li><p>聊聊 MQTT：EMQX 和 HiveMQ</p></li><li><p>业界产品拆解：Confluent Kora</p></li><li><p>业界产品拆解：Pulsar Ursa</p></li></ol><p>如果你有更多想要了解的内容，也欢迎在留言区写下你的问题，我们共同探讨。</p><p>另外，由于年底我的工作较为繁忙，也为了内容能够精益求精，加更的部分，频率我会放缓一些，每节课的间隔大致会在一到两周。还请各位同学多多理解。好，闲话就到这里，我们课程里见！</p>',10)])])}const m=p(r,[["render",l]]);export{f as __pageData,m as default};
